import { Check } from "lucide-react";

const steps = [
  { id: 1, label: "Capability Review", state: "complete" },
  { id: 2, label: "Working Data", state: "active" },
  { id: 3, label: "Review & Submit", state: "upcoming" },
] as const;

export function SurveyStepper() {
  return (
    <nav aria-label="Survey progress" className="my-4 flex items-center">
      {steps.map((step, index) => (
        <div
          className="flex min-w-0 flex-1 items-center last:flex-none"
          key={step.id}
        >
          <div className="flex shrink-0 items-center gap-3">
            <span
              className={[
                "flex h-7 w-7 items-center justify-center rounded-full text-[11px] font-semibold",
                step.state === "complete"
                  ? "bg-[#16A34A] text-white"
                  : step.state === "active"
                    ? "bg-survey-orange text-white shadow-[0_0_0_3px_rgba(234,88,12,0.11)]"
                    : "bg-survey-step text-[#66809B]",
              ].join(" ")}
            >
              {step.state === "complete" ? (
                <Check className="h-3.5 w-3.5" strokeWidth={2.7} />
              ) : (
                step.id
              )}
            </span>
            <span
              className={[
                "whitespace-nowrap text-[11px] leading-4",
                step.state === "active"
                  ? "font-semibold text-[#111827]"
                  : "font-medium text-[#52616F]",
              ].join(" ")}
            >
              {step.label}
            </span>
          </div>

          {index < steps.length - 1 ? (
            <span
              className={[
                "mx-5 h-px min-w-10 flex-1",
                index === 0 ? "bg-[#16A34A]" : "bg-[#DDE6F0]",
              ].join(" ")}
            />
          ) : null}
        </div>
      ))}
    </nav>
  );
}
